pub struct cudaGraphRecaptureCallbackData {
    pub callbackFunc: cudaGraphRecaptureCallback_t,
    pub userData: *mut ::std::os::raw::c_void,
}
#[test]
fn bindgen_test_layout_cudaGraphRecaptureCallbackData() {
    const UNINIT: ::std::mem::MaybeUninit<cudaGraphRecaptureCallbackData> =
        ::std::mem::MaybeUninit::uninit();
    let ptr = UNINIT.as_ptr();
    assert_eq!(
        ::std::mem::size_of::<cudaGraphRecaptureCallbackData>(),
        16usize,
        concat!("Size of: ", stringify!(cudaGraphRecaptureCallbackData))
    );
    assert_eq!(
        ::std::mem::align_of::<cudaGraphRecaptureCallbackData>(),
        8usize,
        concat!("Alignment of ", stringify!(cudaGraphRecaptureCallbackData))
    );
    assert_eq!(
        unsafe { ::std::ptr::addr_of!((*ptr).callbackFunc) as usize - ptr as usize },
        0usize,
        concat!(
            "Offset of field: ",
            stringify!(cudaGraphRecaptureCallbackData),
            "::",
            stringify!(callbackFunc)
        )
    );
    assert_eq!(
        unsafe { ::std::ptr::addr_of!((*ptr).userData) as usize - ptr as usize },
        8usize,
        concat!(
            "Offset of field: ",
            stringify!(cudaGraphRecaptureCallbackData),
            "::",
            stringify!(userData)
        )
    );
}
